package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Maps an owner's {@link MembershipPoints membership points} to a numeric level from 1 to 4:
 * 1 for 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6 or more.
 */
public final class MembershipLevel {

    private MembershipLevel() {
    }

    public static int of(int membershipPoints) {
        if (membershipPoints >= 6) {
            return 4;
        }
        if (membershipPoints >= 4) {
            return 3;
        }
        if (membershipPoints >= 2) {
            return 2;
        }
        return 1;
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Derives an owner's membership tier: {@code GOLD} for a household of 3 or more members, else
 * {@code SILVER} for an owner with an email and no namesakes ({@code namesakeCount} of 0), otherwise
 * {@code BRONZE}.
 */
public final class MembershipTier {

    private MembershipTier() {
    }

    public static String of(Owner owner, int namesakeCount, int householdSize) {
        if (householdSize >= 3) {
            return "GOLD";
        }
        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
        return namesakeCount == 0 && hasEmail ? "SILVER" : "BRONZE";
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Counts the members of an owner's household: the owners sharing this owner's {@link HouseholdId}
 * (last name and postcode). The owner itself is included, so a freshly created owner counts towards
 * its own household total.
 */
public final class HouseholdSize {

    private HouseholdSize() {
    }

    public static int of(Owner owner, OwnerRepository repository) {
        String householdId = HouseholdId.of(owner);
        int count = 0;
        for (Owner other : repository.findAll()) {
            if (householdId.equals(HouseholdId.of(other))) {
                count++;
            }
        }
        return count;
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Derives the stable identifier of an owner's household: the first 12 hex characters of SHA-256 over
 * {@code normalizedLastName + '|' + postcode} (last name compared case-insensitively with collapsed
 * whitespace, exactly as {@link RejectDuplicateOwnerHousehold} groups them). Every owner sharing a
 * last name and postcode therefore maps to the same value without any stored state, so a household
 * is keyed on {@code (lastName, postcode)} alone.
 */
public final class HouseholdId {

    private HouseholdId() {
    }

    public static String of(Owner owner) {
        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
        String key = normalize(owner.getLastName()) + '|' + postcode;
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
            StringBuilder id = new StringBuilder(12);
            for (int i = 0; i < 6; i++) {
                id.append(String.format("%02X", digest[i]));
            }
            return id.toString();
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException(ex);
        }
    }

    private static String normalize(String value) {
        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}

